CREATE TABLE public.grn_drafts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),store_id uuid NOT NULL DEFAULT public.current_store_id() REFERENCES public.stores(id),created_by uuid NOT NULL DEFAULT auth.uid(),payload jsonb NOT NULL DEFAULT '{}'::jsonb,version integer NOT NULL DEFAULT 1,posted_grn_id uuid REFERENCES public.grns(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.grn_drafts TO authenticated; GRANT ALL ON public.grn_drafts TO service_role;
ALTER TABLE public.grn_drafts ENABLE ROW LEVEL SECURITY;
CREATE POLICY "stock staff read own GRN drafts" ON public.grn_drafts FOR SELECT TO authenticated USING(store_id=public.current_store_id() AND public.can_manage_stock(auth.uid()));
CREATE OR REPLACE FUNCTION public.save_grn_draft(p_id uuid,p_version integer,p_payload jsonb) RETURNS public.grn_drafts LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE d public.grn_drafts; sid uuid:=public.current_store_id(); BEGIN IF sid IS NULL OR NOT public.can_manage_stock(auth.uid()) THEN RAISE EXCEPTION 'Not authorised'; END IF; IF jsonb_typeof(p_payload) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'Invalid draft'; END IF; IF p_id IS NULL THEN INSERT INTO public.grn_drafts(store_id,created_by,payload) VALUES(sid,auth.uid(),p_payload) RETURNING * INTO d; ELSE UPDATE public.grn_drafts SET payload=p_payload,version=version+1,updated_at=now() WHERE id=p_id AND store_id=sid AND version=p_version AND posted_grn_id IS NULL RETURNING * INTO d; IF NOT FOUND THEN RAISE EXCEPTION 'Draft changed or was already received. Reopen it before saving.'; END IF; END IF; RETURN d; END $$;
CREATE OR REPLACE FUNCTION public.post_grn_draft(p_id uuid,p_version integer) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE d public.grn_drafts; result jsonb; items jsonb; BEGIN IF public.current_store_id() IS NULL OR NOT public.can_manage_stock(auth.uid()) THEN RAISE EXCEPTION 'Not authorised'; END IF; SELECT * INTO d FROM public.grn_drafts WHERE id=p_id AND store_id=public.current_store_id() FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Draft not found'; END IF; IF d.posted_grn_id IS NOT NULL THEN SELECT jsonb_build_object('id',id,'grn_number',grn_number) INTO result FROM public.grns WHERE id=d.posted_grn_id AND store_id=d.store_id; RETURN result; END IF; IF d.version<>p_version THEN RAISE EXCEPTION 'Draft changed. Reopen and review it again.'; END IF; SELECT jsonb_agg(jsonb_build_object('product_id',x->>'product_id','quantity',(x->>'quantity')::numeric,'unit_cost',(x->>'unit_cost')::numeric)) INTO items FROM jsonb_array_elements(d.payload->'lines') x WHERE coalesce(x->>'product_id','')<>'' OR coalesce(x->>'quantity','')<>'' OR coalesce(x->>'unit_cost','')<>'';
result:=public.receive_goods_currency((d.payload->>'supplier')::uuid,d.payload->>'invoice',items,coalesce(nullif(d.payload->>'paid',''),'0')::numeric,d.payload->>'note',d.payload->>'currency',(d.payload->>'rate')::numeric,d.payload->>'method'); UPDATE public.grn_drafts SET posted_grn_id=(result->>'id')::uuid,version=version+1,updated_at=now() WHERE id=d.id; IF (result->>'id') IS NULL THEN RAISE EXCEPTION 'Receipt could not be linked'; END IF; RETURN result; END $$;
REVOKE ALL ON FUNCTION public.save_grn_draft(uuid,integer,jsonb),public.post_grn_draft(uuid,integer) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.save_grn_draft(uuid,integer,jsonb),public.post_grn_draft(uuid,integer) TO authenticated;